def transform(grid):
    """
    Rule: Objects fall down so that empty rows between objects are eliminated,
    packing them as closely as possible just above the red bar at bottom.
    """
    h, w = len(grid), len(grid[0])

    # Separate objects by value, tracking their bottom rows
    objects = {}
    for v in range(10):
        if v == 0:
            continue
        objects[v] = []

    # Find bottom row for each value
    for v in objects:
        for r in range(h - 1, -1, -1):  # Check from bottom
            if v in grid[r]:
                objects[v].append(r)
                break

    # Sort values by their bottom row - objects with lower bottom rows stay higher
    # Actually, we need to preserve column positions
    # Let's instead: collect all non-zero cells, sort by (col, bottom_row) then distribute

    # Actually simpler: just collect all objects at each column
    objects_by_col = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                if c not in objects_by_col:
                    objects_by_col[c] = []
                if v not in objects_by_col[c]:
                    objects_by_col[c].append(v)

    # For each column, build output by taking objects from bottom up
    result = [[0] * w for _ in range(h)]

    # Find bottom red row - it stays fixed
    bottom_row = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)) and len(grid[r]) > 0:
            bottom_row = r
            break

    # Collect all column data with bottom rows
    col_objects = {}  # col -> [(value, bottom_row)]
    for c in range(w):
        for r in range(h):
            v = grid[r][c]
            if v == 2 and bottom_row == r - 1:  # part of red bar
                break
            if v != 0:
                if c not in col_objects:
                    col_objects[c] = []
                if v not in col_objects[c]:
                    col_objects[c].append((v, r))

    for c in col_objects:
        col_data = sorted(col_objects[c], key=lambda x: x[1])
        # Reverse to get bottom-most first
        col_data.reverse()

        new_base_row = h - 1 if bottom_row == h - 1 else h - 2  # Just above red bar
        for v, old_row in col_data:
            result[new_base_row][c] = v
            new_base_row -= 1

    return result

