def transform_compact(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * w for _ in range(h)]

    # Red bar stays at bottom (or h-2 if wanting 2 empty rows above)
    for c in range(w):
        result[h-2][c] = grid[h-1][c]

    # Non-zero cells from non-bottom rows: count them, place from row h-3 down
    # But we need to preserve column positions
    for c in range(w):
        col_nonzero = [v for r in range(h-2) for v in [grid[r][c]] if v != 0]
        row = h - 4  # Start just above red
        for v in col_nonzero:
            if row >= 0:
                result[row][c] = v
                row -= 1
        # Fill rest with 0
        for row in range(h-3, -1, -1):
            if result[row][c] == 0 and row >= -1:
                pass

    return result

