def transform_shift_toward_red_fixed(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * w for _ in range(h)]

    shifts = {1: 4, 3: 5, 4: 5, 5: 2, 6: 4, 7: 5, 8: 6, 9: 4}

    red_row = 0
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            red_row = r
            break

    for c in range(w):
        result[red_row][c] = 2

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != 2:
                shift = shifts.get(v, 2)
                if red_row == h - 1:
                    new_r = r + shift
                else:
                    new_r = r - shift

                # Clamp: if negative, clamp to 1 (first row after red at row 0)
                # If positive and would exceed available rows, clamp to h-1
                if new_r < 1:  # Can't go to red row (0)
