def transform_final_shift(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * w for _ in range(h)]

    shifts = {1: 4, 3: 5, 4: 5, 5: 2, 6: 4, 7: 5, 8: 6, 9: 4}

    # Find red row
    red_row = 0
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            red_row = r
            break

    # Place red bar first
    for c in range(w):
        result[red_row][c] = 2

    # Apply shifts for each cell - direction depends on red position
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != 2:
                s = shifts.get(v, 2)
                if red_row == 0:
                    # Red at top: shift UP (substract shift)
                    new_r = r - s
                else:
                    # Red at bottom: shift DOWN (add shift)
                    new_r = r + s

                # Clamp: can't land on red row, and won't let them wrap
                # Since red is at fixed position, clamp to stay on that side
                if red_row == 0:
                    # All objects are below red, shift up but keep >= 1 (row 0 is red)
                    if new_r < 1:
                        new_r = 1
                    if new_r > red_row + 8:  # max available slots
                        new_r = red_row + 8
                else:
                    # Red at bottom, keep below red_row
                    if new_r < red_row:
                        new_r = red_row
                    if new_r >= h:
                        new_r = h - 1

                result[new_r][c] = v

    return result

