def transform_first_wins(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * w for _ in range(h)]
    shifts = {1: 4, 3: 5, 4: 5, 5: 2, 6: 4, 7: 5, 8: 6, 9: 4}
    red_row = 0

    # Process columns in order, cells in order by row
    cols_by_column = []
    for c in range(w):
        cells = sorted([(grid[r][c], r) for r in range(1, h) if grid[r][c] != 0 and grid[r][c] != 2], key=lambda x: x[1])
        cols_by_column.append(cells)

    for c, cells in enumerate(cols_by_column):
        for v, r in cells:
            s = shifts.get(v, 2)
            new_r = r - s
            if new_r < 1 or new_r >= h:
                continue
            # If cell is already occupied, skip (first-wins, don't overwrite)
            if result[new_r][c] != 0:
                continue
            result[new_r][c] = v

    for c in range(w):
        result[red_row][c] = 2

    return result

