def transform_correct_full(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * w for _ in range(h)]
    shifts = {1: 4, 3: 5, 4: 5, 5: 2, 6: 4, 7: 5, 8: 6, 9: 4}
    red_row = 0
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            red_row = r
            break

    placements = []
    for c in range(w):
        cells_above = sorted([(grid[r][c], r) for r in range(red_row) if grid[r][c] != 0 and grid[r][c] != 2], key=lambda x: x[1])
        cells_below = sorted([(grid[r][c], r) for r in range(red_row+1, h) if grid[r][c] != 0 and grid[r][c] != 2], key=lambda x: x[1])

        for v, r in cells_above:
            s = shifts.get(v, 2)
            new_r = r + s
            if 0 <= new_r < red_row:
                placements.append(((c, new_r), v))
                result[new_r][c] = v

        for v, r in cells_below:
            s = shifts.get(v, 2)
            new_r = r - s
            if red_row+1 <= new_r < h:
                placements.append(((c, new_r), v))
                result[new_r][c] = v

    for c in range(w):
        result[red_row][c] = 2

    return placements, result

